            '11. Madde 9: Başvuru yöntemi' => [
                'kvkk.m9.baslik' => ['Madde başlığı', 'Başvuru yöntemi', 'line', 'Hukuki metin; hukuk danışmanınıza sorun. Başlık hem maddenin üstünde hem Maddeler listesinde görünür.', ['max' => 80]],
                'kvkk.m9.f1' => ['1. fıkra: başvuru yöntemi', 'Haklarınıza ilişkin taleplerinizi, kimliğinizi tespit etmemize imkân verecek bilgilerle birlikte yukarıdaki adresimize yazılı olarak ya da daha önce bize bildirdiğiniz ve kayıtlarımızda bulunan e-posta adresinizden {eposta_baglanti} adresine iletebilirsiniz.', 'text', 'Hukuki metin; hukuk danışmanınıza sorun.', ['vars' => ['eposta_baglanti', 'firma', 'firma_kisa'], 'need' => ['eposta_baglanti'], 'max' => 2000]],
                'kvkk.m9.f2' => ['2. fıkra: yanıt süresi ve şikâyet hakkı', 'Başvurunuz, niteliğine göre en kısa sürede ve en geç otuz gün içinde sonuçlandırılır; işlem kural olarak ücretsizdir. Formu gönderdiğiniz hâlde mesajınıza dönüş almadıysanız, otomatik süzgecimiz mesajınızı yanlışlıkla istenmeyen ileti saymış olabilir; telefonla ya da e-postayla bize ulaşmanız yeterlidir. Başvurunuzun reddedilmesi, verilen cevabı yetersiz bulmanız ya da süresinde cevap verilmemesi hâlinde Kişisel Verileri Koruma Kurulu’na şikâyette bulunabilirsiniz.', 'text', '', ['vars' => ['firma', 'firma_kisa', 'eposta_baglanti'], 'max' => 2000]],
                'kvkk.m9.sade' => ['Sade Türkçesi', 'Bize yazın; en geç otuz gün içinde, ücretsiz cevap veririz.', 'text', 'Maddenin altındaki “Sade Türkçesi” açılır kutusunda görünür.', ['max' => 500]],
            ],
